def _row_neutral_losses(ref_mz: np.ndarray, ref_pmz, dtype) -> np.ndarray:
    """
    Neutral losses (precursor - m/z) of a single row spectrum.

    The losses are computed exactly like the library-side neutral losses in
    :func:`~matchms.similarity.flash_utils._build_library_index` (elementwise in the index
    `dtype`). Using the same precision on both sides guarantees that a spectrum compared with
    itself produces identical loss values, so it matches itself even for a zero tolerance or a
    low-precision storage dtype.

    Returns an empty array if the row has no (finite) precursor m/z.
    """
    if ref_pmz is None:
        return np.zeros(0, dtype=dtype)
    pmz = np.asarray(ref_pmz, dtype=dtype)
    if not np.isfinite(pmz):
        return np.zeros(0, dtype=dtype)
    pmz_per_peak = np.full(ref_mz.shape, pmz, dtype=dtype)
    return pmz_per_peak - ref_mz.astype(dtype, copy=False)


